private static void deleteDirectoryOnExit(File f) throws SecurityException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteDirectoryOnExit(child);
            }
        }
    }
    f.deleteOnExit();
}

