protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Map each vertex to its incident edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }

    // Build ordered list of edges that form the tour
    List<E> ordered = new ArrayList<>(tour.size());
    Set<E> used = new HashSet<>();
    V start = adjacency.keySet().iterator().next();
    V current = start;

    while (used.size() < tour.size()) {
        List<E> edges = adjacency.get(current);
        E nextEdge = null;
        for (E e : edges) {
            if (!used.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) break; // safety

        ordered.add(nextEdge);
        used.add(nextEdge);

        // Determine the next vertex along the tour
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        current = src.equals(current) ? tgt : src;
    }

    return new GraphPath<>(graph, ordered);
}

