                String hex = input.substring(i + 2, i + 4);
                try {
                    int code = Integer.parseInt(hex, 16);
                    result.append((char) code);
                } catch (NumberFormatException e) {
                    result.append("\\x").append(hex);
                }
                i += 3;
                continue;
            } else {
                switch (next) {
                    case 'b':
                        result.append('\b');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case 'n':
                        result.append('\n');
                        break;
