private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int first = bb.get(i) & 0xFF;
    int codePoint = 0;
    int len = 0;
    if ((first >> 7) == 0) {                     // 1-byte sequence
        codePoint = first;
        len = 1;
    } else if ((first >> 5) == 0b110) {           // 2-byte sequence
        int second = bb.get(i + 1) & 0xFF;
        codePoint = ((first & 0b11111) << 6) | (second & 0b111111);
        len = 2;
    } else if ((first >> 4) == 0b1110) {           // 3-byte sequence
        int second = bb.get(i + 1) & 0xFF;
        int third = bb.get(i + 2) & 0xFF;
        codePoint = ((first & 0b1111) << 12)
                  | ((second & 0b111111) << 6)
                  | (third & 0b111111);
        len = 3;
    } else if ((first >> 3) == 0b11110) {          // 4-byte sequence
        int second = bb.get(i + 1) & 0xFF;
        int third = bb.get(i + 2) & 0xFF;
        int fourth = bb.get(i + 3) & 0xFF;
        codePoint = ((first & 0b111) << 18)
                  | ((second & 0b111111) << 12)
                  | ((third & 0b111111) << 6)
                  | (fourth & 0b111111);
        len = 4;
    } else {                                      // Invalid first byte
        codePoint = 0xFFFD;  // Replacement character
        len = 1;
    }
    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        codePoint -= 0x10000;
        sb.append((char) ((codePoint >> 10) + 0xD800));
        sb.append((char) ((codePoint & 0x3FF) + 0xDC00));
    }
    return i + len;
}

