public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    int start = 0;
    if (path.startsWith("/")) {
        start = 1;
    }
    String sub = path.substring(start);
    // Keep trailing empty segments (e.g. "/a/b/") by specifying limit -1
    String[] parts = sub.split("/", -1);
    for (String part : parts) {
        String seg = part;
        if (decode && !seg.isEmpty()) {
            try {
                seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(seg));
    }
    return result;
}

